/**
 * Detect optimal collision type from geometry.
 *
 * Analyzes the geometry and returns the recommended collision type.
 * Used when BodyCollisionType.AUTO is specified (default).
 *
 * Detection priority:
 * 1. Known geometry type → mapped collision type
 * 2. High triangle count (>200) → FULL
 * 3. Aspect ratio analysis for capsule-like shapes
 * 4. Default → BOX
 *
 * @param {THREE.BufferGeometry} geometry - The body's geometry
 * @returns {number} Optimal BodyCollisionType value
 *
 * @example
 * ```js
 * import { detectCollisionType, BodyCollisionType } from '@three-blocks/pro';
 *
 * const type = detectCollisionType(mesh.geometry);
 * if (type === BodyCollisionType.SPHERE) {
 *   console.log('Using fast sphere collision');
 * }
 * ```
 */
export function detectCollisionType(geometry: THREE.BufferGeometry): number;
/**
 * Get collision type name for debugging.
 *
 * @param {number|null} type - The collision type value
 * @returns {string} Human-readable name
 */
export function getCollisionTypeName(type: number | null): string;
/**
 * Check if collision type uses SDF (analytical) collision.
 *
 * @param {number} type - The collision type value
 * @returns {boolean} True if SDF-based (SPHERE or CAPSULE)
 */
export function isSdfCollisionType(type: number): boolean;
/**
 * Check if collision type uses BVH collision.
 *
 * @param {number} type - The collision type value
 * @returns {boolean} True if BVH-based (BOX or FULL)
 */
export function isBvhCollisionType(type: number): boolean;
/**
 * Check if collision type is Points-based.
 *
 * @param {number} type - The collision type value
 * @returns {boolean} True if POINTS type
 */
export function isPointsCollisionType(type: number): boolean;
export const BodyCollisionType: Readonly<{
    /**
     * Auto-detect collision type from geometry.
     *
     * Uses helper to analyze geometry and select optimal mode:
     * - SphereGeometry → SPHERE (fastest)
     * - CapsuleGeometry → CAPSULE
     * - Simple convex shapes → BOX
     * - Complex shapes → FULL
     *
     * @type {null}
     */
    AUTO: null;
    /**
     * SDF Sphere-Sphere collision (O(1) per pair).
     *
     * Simple distance check between sphere centers.
     * Fastest possible collision detection.
     *
     * Best for: SphereGeometry, IcosahedronGeometry (high detail)
     *
     * @type {number}
     */
    SPHERE: number;
    /**
     * SDF Capsule-Capsule collision (O(1) per pair).
     *
     * Segment-segment distance with radii.
     * Very fast, ideal for character-like shapes.
     *
     * Best for: CapsuleGeometry, CylinderGeometry
     *
     * @type {number}
     */
    CAPSULE: number;
    /**
     * BVH-to-Box collision (O(log n) per pair).
     *
     * Uses A's BVH shapecast against B's transformed bounding box.
     * Good balance of speed and accuracy for convex shapes.
     *
     * Best for: BoxGeometry, most convex shapes
     *
     * @type {number}
     */
    BOX: number;
    /**
     * Fast BVH-to-BVH collision (O(log n × log m) per pair).
     *
     * Uses intersectsGeometry for boolean detection + AABB approximation.
     * Good balance of speed and accuracy for concave shapes.
     *
     * Best for: TorusKnotGeometry, complex meshes, concave shapes
     *
     * @type {number}
     */
    FULL: number;
    /**
     * Precise BVH-to-BVH collision (O(n log n) per pair).
     *
     * Uses bvhcast with triangle-triangle distance tests.
     * Most accurate but slower. Use when exact contact points are critical.
     *
     * Best for: When precise contact normal/point is required
     *
     * @type {number}
     */
    FULL_PRECISE: number;
    /**
     * PointsBVH collision for point cloud geometry (O(log n) per pair).
     *
     * Uses three-mesh-bvh PointsBVH for spatial acceleration.
     * Each point is treated as a sphere with configurable radius.
     *
     * Best for: Point clouds, gaussian splats, LiDAR data as static collision geometry
     *
     * @type {number}
     */
    POINTS: number;
}>;
